    static int request(String path,Object body,String user,String password,String method)throws Exception{var client=HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).build();var builder=HttpRequest.newBuilder(URI.create(url()+path)).timeout(java.time.Duration.ofSeconds(8)).header("Content-Type","application/json").header("Authorization","Basic "+Base64.getEncoder().encodeToString((user+":"+password).getBytes()));builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(encode(body)));return client.send(builder.build(),HttpResponse.BodyHandlers.discarding()).statusCode();}
